-- Preserve individual decisions; covered is a distinct assignment provenance.
CREATE TABLE assignments_oversight (id TEXT PRIMARY KEY,workId TEXT NOT NULL REFERENCES work(id),recipientId TEXT NOT NULL REFERENCES actors(id),state TEXT NOT NULL CHECK(state IN ('proposed','accepted','declined','withdrawn','covered')),decidedAt INTEGER);
INSERT INTO assignments_oversight SELECT * FROM assignments;
DROP TABLE assignments;
ALTER TABLE assignments_oversight RENAME TO assignments;
CREATE UNIQUE INDEX assignment_work ON assignments(workId);
ALTER TABLE streams ADD COLUMN parentId TEXT REFERENCES streams(id);
ALTER TABLE streams ADD COLUMN approvalId TEXT REFERENCES stream_approvals(id);
ALTER TABLE streams ADD COLUMN coverageApprovalId TEXT REFERENCES stream_approvals(id);
ALTER TABLE streams ADD COLUMN phase TEXT NOT NULL DEFAULT '';
ALTER TABLE streams ADD COLUMN progressSummary TEXT NOT NULL DEFAULT '';
ALTER TABLE streams ADD COLUMN reportedBy TEXT REFERENCES actors(id);
ALTER TABLE streams ADD COLUMN reportedAt INTEGER;
ALTER TABLE streams ADD COLUMN outcomeAvailableAt INTEGER;
ALTER TABLE streams ADD COLUMN outcomeRevision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE streams ADD COLUMN planRevision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE streams ADD COLUMN assessment TEXT;
ALTER TABLE streams ADD COLUMN assessedBy TEXT REFERENCES actors(id);
ALTER TABLE streams ADD COLUMN assessedAt INTEGER;
ALTER TABLE streams ADD COLUMN reviewRequested INTEGER NOT NULL DEFAULT 0 CHECK(reviewRequested IN (0,1));
CREATE INDEX streams_parent ON streams(parentId);
CREATE TABLE stream_approvals(id TEXT PRIMARY KEY,streamId TEXT NOT NULL REFERENCES streams(id),scopeRevision INTEGER NOT NULL,actorId TEXT NOT NULL REFERENCES actors(id),scope TEXT NOT NULL,createdAt INTEGER NOT NULL);
CREATE TRIGGER stream_approvals_no_update BEFORE UPDATE ON stream_approvals BEGIN SELECT RAISE(ABORT,'approvals are immutable'); END;
CREATE TRIGGER stream_approvals_no_delete BEFORE DELETE ON stream_approvals BEGIN SELECT RAISE(ABORT,'approvals are immutable'); END;
ALTER TABLE change_meta ADD COLUMN coverageApprovalId TEXT REFERENCES stream_approvals(id);
ALTER TABLE change_meta ADD COLUMN deliveredAt INTEGER;
ALTER TABLE change_meta ADD COLUMN deliveredBy TEXT REFERENCES actors(id);
ALTER TABLE change_meta ADD COLUMN reviewRequested INTEGER NOT NULL DEFAULT 0 CHECK(reviewRequested IN (0,1));
ALTER TABLE stream_context ADD COLUMN answer TEXT;
ALTER TABLE stream_context ADD COLUMN answeredBy TEXT REFERENCES actors(id);
ALTER TABLE stream_context ADD COLUMN answeredAt INTEGER;
CREATE TABLE human_actions(id TEXT PRIMARY KEY,streamId TEXT NOT NULL REFERENCES streams(id),createdBy TEXT NOT NULL REFERENCES actors(id),title TEXT NOT NULL,description TEXT NOT NULL,doneWhen TEXT NOT NULL,ownerId TEXT NOT NULL REFERENCES actors(id),waitingOn TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','in_progress','done','cancelled')),response TEXT NOT NULL DEFAULT '',respondedBy TEXT REFERENCES actors(id),revision INTEGER NOT NULL DEFAULT 1,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL);
CREATE INDEX human_actions_stream ON human_actions(streamId,state);
CREATE TABLE oversight_nodes(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('stream','change','human_action')));
INSERT INTO oversight_nodes SELECT id,'stream' FROM streams;
INSERT INTO oversight_nodes SELECT id,'change' FROM work;
CREATE TRIGGER streams_node AFTER INSERT ON streams BEGIN INSERT INTO oversight_nodes VALUES (new.id,'stream'); END;
CREATE TRIGGER changes_node AFTER INSERT ON work BEGIN INSERT INTO oversight_nodes VALUES (new.id,'change'); END;
CREATE TRIGGER actions_node AFTER INSERT ON human_actions BEGIN INSERT INTO oversight_nodes VALUES (new.id,'human_action'); END;
CREATE TABLE flow_dependencies(targetId TEXT NOT NULL REFERENCES oversight_nodes(id),sourceId TEXT NOT NULL REFERENCES oversight_nodes(id),stage TEXT NOT NULL CHECK(stage IN ('start','deliver')),condition TEXT NOT NULL CHECK(condition IN ('output_available','integrated','outcome_available','outcome_accepted','done')),reason TEXT NOT NULL,PRIMARY KEY(targetId,sourceId,stage),CHECK(targetId!=sourceId));
INSERT INTO flow_dependencies SELECT changeId,requiresId,CASE stage WHEN 'integrate' THEN 'deliver' ELSE stage END,condition,reason FROM change_dependencies;
CREATE INDEX flow_source ON flow_dependencies(sourceId);
CREATE TABLE stream_outputs(id TEXT PRIMARY KEY,streamId TEXT NOT NULL REFERENCES streams(id),kind TEXT NOT NULL,url TEXT NOT NULL,label TEXT NOT NULL,codeRevision TEXT NOT NULL DEFAULT '',state TEXT NOT NULL,reportedBy TEXT NOT NULL REFERENCES actors(id),reportedAt INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(streamId,url,reportedBy));
